@media (max-width: 639.98px) {
  .vc-dialog,
  .vc-dash-confirm {
    align-items: flex-end;
    justify-content: stretch;
    padding: max(0.5rem, env(safe-area-inset-top, 0px)) 0 0;
  }

  .vc-dialog__panel,
  .vc-dash-confirm__panel {
    width: 100%;
    max-width: 100%;
    max-height: min(90dvh, calc(100dvh - max(0.5rem, env(safe-area-inset-top, 0px))));
    display: flex;
    flex-direction: column;
    overflow: hidden;
    -webkit-overflow-scrolling: touch;
    -webkit-mask-image: -webkit-radial-gradient(white, black);
    border-radius: 1.35rem 1.35rem 0 0;
    padding: 0;
    transform: translateY(12px);
  }

  .vc-dialog.is-open .vc-dialog__panel,
  .vc-dash-confirm.is-open .vc-dash-confirm__panel {
    transform: none;
  }

  .vc-dialog__panel::before,
  .vc-dash-confirm__panel::before {
    content: "";
    display: block;
    flex: 0 0 auto;
    width: 2.75rem;
    height: 0.3rem;
    margin: 0.45rem auto 0;
    border-radius: 999px;
    background: rgba(247, 236, 223, 0.28);
  }

  .vc-dialog__icon,
  .vc-dash-confirm__icon {
    flex: 0 0 auto;
    margin: 0.7rem 1.1rem 0;
  }

  .vc-dialog__title,
  .vc-dash-confirm__title {
    flex: 0 0 auto;
    font-size: 1.2rem;
    margin: 0.55rem 1.1rem 0;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid rgba(232, 201, 168, 0.14);
  }

  .vc-dialog__text,
  .vc-dash-confirm__text,
  .vc-dialog__field,
  .vc-dialog__actions,
  .vc-dash-confirm__actions {
    flex: 0 0 auto;
    margin-left: 1.1rem;
    margin-right: 1.1rem;
  }

  .vc-dialog__text,
  .vc-dash-confirm__text {
    font-size: 0.95rem;
    line-height: 1.45;
    max-height: min(42dvh, 16rem);
    overflow: auto;
    -webkit-overflow-scrolling: touch;
    margin-top: 0.65rem;
  }

  .vc-dialog__actions,
  .vc-dash-confirm__actions {
    margin-top: 0.95rem;
    margin-bottom: calc(1.05rem + env(safe-area-inset-bottom, 0px));
  }

  .vc-dialog__actions:not(.vc-dialog__actions--stack),
  .vc-dash-confirm__actions {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .vc-dialog__btn,
