    width: 100%;
    justify-content: center;
    min-height: 2.85rem;
    font-size: 0.95rem;
  }

  .vc-dialog__input,
  .vc-dialog__textarea {
    min-height: 2.85rem;
    font-size: 1rem;
  }

  .vc-dialog__textarea {
    min-height: 7.5rem;
  }
}

