.vc-dash-tk__stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: 0.75rem;
}

.vc-dash-tk__stat {
  padding: 0.9rem 1rem;
  border-radius: 0.95rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.18);
}

.vc-dash-tk__stat-label {
  display: block;
  font-size: 0.78rem;
  opacity: 0.72;
  margin-bottom: 0.35rem;
}

.vc-dash-tk__stat-value {
  font-size: 1.35rem;
}

.vc-dash-tk__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.vc-dash-tk__title {
  margin: 0;
  font-size: 1.05rem;
}

.vc-dash-tk__filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1rem;
  align-items: end;
  margin-bottom: 0.85rem;
}

.vc-dash-tk__list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.vc-dash-tk__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding: 0.85rem 0.95rem;
  border-radius: 0.95rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.18);
}

.vc-dash-tk__meta {
  margin-top: 0.35rem;
  font-size: 0.82rem;
  opacity: 0.78;
}

.vc-dash-tk__pill {
  display: inline-block;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 0.75rem;
}

.vc-dash-tk__row-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.vc-dash-tk__empty {
  text-align: center;
  padding: 1.5rem 1rem;
  opacity: 0.8;
}

.vc-dash-tk__pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1rem;
}

.vc-dash-tk-tx-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.45rem 0.55rem;
  margin: 1rem -0.15rem 0;
  padding: 0.85rem 0.35rem 0.15rem;
  border-top: 1px solid rgba(var(--vc-sand-rgb), 0.14);
}

.vc-dash-tk-tx-pager[hidden] {
  display: none !important;
}

.vc-dash-tk-tx-pager__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  margin: 0;
  padding: 0;
  border-radius: 0.8rem;
  border: 1px solid rgba(196, 149, 98, 0.26);
  background: rgba(196, 149, 98, 0.08);
  color: #f4efe8;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  cursor: var(--vc-cursor-pointer);
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.12s ease;
}

.vc-dash-tk-tx-pager__btn i {
  font-size: 0.82rem;
  line-height: 1;
}

.vc-dash-tk-tx-pager__btn:not(:disabled):hover,
.vc-dash-tk-tx-pager__btn:not(:disabled):focus-visible {
  border-color: rgba(196, 149, 98, 0.48);
  background: rgba(196, 149, 98, 0.18);
  color: #fff8ef;
  outline: none;
}

.vc-dash-tk-tx-pager__btn:not(:disabled):active {
  transform: translateY(1px);
}

.vc-dash-tk-tx-pager__btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  box-shadow: none;
}

.vc-dash-tk-tx-pager__meta {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0 0.2rem;
  min-width: 0;
}

.vc-dash-tk-tx-pager__label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(232, 201, 168, 0.68);
}

.vc-dash-tk-tx-pager__pill {
  display: inline-flex;
  align-items: baseline;
  gap: 0.28rem;
  padding: 0.34rem 0.7rem;
  border-radius: 999px;
  border: 1px solid rgba(196, 149, 98, 0.28);
  background: rgba(196, 149, 98, 0.1);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.vc-dash-tk-tx-pager__cur {
  font-size: 0.95rem;
  font-weight: 700;
  color: #f6e7d4;
}

.vc-dash-tk-tx-pager__sep {
  font-size: 0.72rem;
  font-weight: 600;
  color: rgba(232, 201, 168, 0.55);
}

.vc-dash-tk-tx-pager__tot {
  font-size: 0.84rem;
  font-weight: 600;
  color: rgba(244, 239, 232, 0.86);
}

.vc-dash-tk__types {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 0.55rem;
  width: 100%;
}

.vc-dash-tk__type {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0;
  padding: 0.7rem 0.85rem;
  border-radius: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  cursor: var(--vc-cursor-pointer);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.vc-dash-tk__type:hover {
  border-color: rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.07);
}

.vc-dash-tk__type:has(input:checked) {
  border-color: rgba(196, 149, 98, 0.55);
  background: rgba(196, 149, 98, 0.12);
}

.vc-dash-tk__type input {
  margin: 0;
  accent-color: #c49562;
}

.vc-dash-tk-open-filters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.15rem;
  column-gap: 1.15rem;
  row-gap: 1rem;
  align-items: end;
}

.vc-dash-tk-open-filters > .vc-dash-picker {
  min-width: 0;
}

.vc-dash-tk-open-filters__sort {
  grid-column: 1 / -1;
}

.vc-dash-tk-open-filters__mine {
  grid-column: 1 / -1;
}

.vc-dash-tk-open-awaiting {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-weight: 650;
  color: #f0c48a;
}

.vc-dash-tk-open-awaiting.is-no {
  color: rgba(244, 239, 232, 0.55);
  font-weight: 500;
}

.vc-dash-tk-open-link {
  color: inherit;
  text-decoration: none;
}

.vc-dash-tk-open-link:hover {
  color: #f6e7d4;
  text-decoration: underline;
}

.vc-dash-tk-teams {
  display: grid;
  gap: 1rem;
}

.vc-dash-tk-teams__top {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.15rem;
  align-items: stretch;
}

